head.script:
scwin.onpageload = function () {

};

/**
 * @method 
 * @name drawChartData
 * @description [데이터/옵션 분리] 화면에서 조회한 데이터(raw)를 받아 type+옵션과 결합·변환하여 렌더한다. (조회 없음)
 *              - raw 가 순수 배열이면 슬롯 키를 type/모양으로 조합: 배열의배열→columns, 객체배열→json (SLOT 예외테이블 우선)
 *              - raw 가 {columns|json|rows|types|xs…} 형태면 슬롯 키를 그대로 병합 (하위호환)
 *              - config.keys / config.dataOpts 는 data 로 이동
 * @param {String} type       차트 타입 (스크립트에서 제공)  ← 첫번째 파라미터
 * @param {Object} raw        화면에서 조회한 데이터 (executeDynamic 응답의 responseJSON)
 * @param {Object} container  컨테이너(컴포넌트/엘리먼트/id)
 * @param {Object} config     옵션 객체 (type 제외). 생략가능.
 * @hidden N
 * @example
 * var res = await $c.sbm.executeDynamic({ id:"sbm_sbchart", action:url, method:"get", mediatype:"application/json", mode:"asynchronous", isProcessMsg:false });
 * $c.ext.drawChartData("bar", res.responseJSON, chartWrap, { extend:{ bar:{ borderRadius:4 } } });
 */
scwin.drawChartData = function (type, raw, container, config) {
    // 모양으로 슬롯 자동판별의 예외(타입 고정 슬롯). 객체배열이지만 rows 가 필요한 경우 등.
    var SLOT = { imageSingle: "rows" };
    var dataBlock = { type: type };                             // type 은 스크립트에서
    if (raw instanceof Array) {
        // JSON 은 순수 배열만: [[…]]→columns / [{…}]→json (SLOT 예외 우선) → 슬롯 키를 스크립트가 조합
        var slot = SLOT[type] || ((raw.length && (raw[0] instanceof Array)) ? "columns" : "json");
        dataBlock[slot] = raw;
    } else if (raw && typeof raw === "object") {
        // 하위호환: 이미 { columns|json|rows|… } 형태면 슬롯 키를 그대로 병합
        for (var rk in raw) { if (raw.hasOwnProperty(rk) && rk !== "type") { dataBlock[rk] = raw[rk]; } }
    }
    var cfg = config || {};
    var opts = {};
    for (var k in cfg) { if (cfg.hasOwnProperty(k) && k !== "keys" && k !== "dataOpts") { opts[k] = cfg[k]; } }
    if (cfg.keys)     { dataBlock.keys = cfg.keys; }            // 단축: keys 를 스크립트에서
    if (cfg.dataOpts) { for (var dk in cfg.dataOpts) { if (cfg.dataOpts.hasOwnProperty(dk)) { dataBlock[dk] = cfg.dataOpts[dk]; } } }  // 데이터레벨 옵션(keys/labels/imageConf…)
    scwin.__drawSBChart(container, opts, dataBlock);           // 조합: opts.data = dataBlock 후 렌더
};

/**
 * @method 
 * @name drawSBChart
 * @description 화면에서 조회한 데이터블록(raw = {type, columns|json|…} 전체)을 옵션과 결합해 렌더. (조회 없음)
 * @param {Object} container  컨테이너
 * @param {Object} raw        데이터블록 전체 (type/columns/types/xs 등 포함)
 * @param {Object} config     옵션 객체(data 제외)
 * @hidden N
 * @example
 * var res = await $c.sbm.executeDynamic({ id:"sbm_sbchart", action:url, method:"get", mediatype:"application/json", mode:"asynchronous", isProcessMsg:false });
 * scwin.drawSBChart(chartWrap, res.responseJSON, scwin.CHART_CONFIG);   // res.responseJSON = {columns,types,xs} 등
 */
scwin.drawSBChart = function (container, raw, config) {
    scwin.__drawSBChart(container, config || {}, raw);
};


/**
 * @method
 * @name destroyChart
 * @description 컨테이너의 차트 인스턴스를 destroy(전역 resize 리스너 해제)하고 컨테이너를 비운다.
 *              sb.chart.render 는 window resize 리스너를 등록하므로, innerHTML 정리만으로는 리스너가
 *              잔존해 화면 이탈/재진입 후 브라우저 리사이즈 시 제거된 DOM 접근 오류(null.style)가 난다.
 *              차트 화면의 onpageunload 에서 호출할 것. (재렌더 시에는 drawChartData 가 자동 destroy)
 * @param {Object} container  컨테이너(컴포넌트/엘리먼트/id)
 * @hidden N
 * @example
 * scwin.onpageunload = function () { $c.ext.destroyChart(chartTop); };
 */
scwin.destroyChart = function (container) {
    var id = __sbResolveId(container);
    scwin.__destroyById(id);
    var el = id ? document.getElementById(id) : null;
    if (el) { el.innerHTML = ""; }
};

/**
 * @method
 * @name __destroyById
 * @description 레지스트리의 차트 정리 — 캡처해 둔 전역(window) resize 리스너를 직접 제거하고
 *              인스턴스 destroy 호출. 라이브러리의 destroy() 는 자신이 등록한 window resize
 *              리스너를 해제하지 않는 것을 실측으로 확인 — 캡처/직접 제거가 필수.
 * @hidden Y
 */
scwin.__destroyById = function (id) {
    var reg = id ? scwin.__charts[id] : null;
    if (!reg) { return; }
    (reg.resizeFns || []).forEach(function (fn) { window.removeEventListener("resize", fn); });
    try { reg.inst.destroy(); } catch (ignore) { /* 이미 제거된 DOM 등 — 무시 */ }
    delete scwin.__charts[id];
};

// 컨테이너 id → { inst: 차트 인스턴스, resizeFns: 라이브러리가 등록한 resize 리스너 } 레지스트리
scwin.__charts = {};

/**
 * @method
 * @name __drawSBChart
 * @description 조회한 데이터를 설정에 결합하여 sb.chart.render 실행 (라이브러리 전역 로드 지연 방어 포함).
 *              이전 차트는 정리(__destroyById) 후 재렌더. render 가 동기 등록하는 window resize
 *              리스너를 캡처해 함께 보관 — 고아 리스너(화면 이탈/재렌더 후 리사이즈 시 제거된
 *              DOM 에 null.style 접근 오류) 방지.
 * @hidden Y
 */
scwin.__drawSBChart = function (comp, config, data) {
    if (!(window.sb && sb.chart)) {                    // 전역 로드 지연 방어
        setTimeout(function () { scwin.__drawSBChart(comp, config, data); }, 50);
        return;
    }
    var id = __sbResolveId(comp);                      // 컴포넌트/엘리먼트/문자열 id 모두 허용
    scwin.__destroyById(id);                           // 이전 차트 정리 — 리스너 해제
    var el = document.getElementById(id);
    if (el) { el.innerHTML = ""; }                     // 재진입 시 이전 SVG 제거
    config.data = data;                                // 조회 데이터 결합 (type 포함)
    // render 중 등록되는 window resize 리스너 캡처 (동기 등록 실측 확인)
    var captured = [];
    var origAdd = window.addEventListener;
    window.addEventListener = function (type, fn) {
        if (type === "resize") { captured.push(fn); }
        return origAdd.apply(window, arguments);
    };
    var inst;
    try {
        inst = sb.chart.render("#" + id, config);
    } finally {
        window.addEventListener = origAdd;             // 어떤 경우에도 원복
    }
    scwin.__charts[id] = { inst: inst, resizeFns: captured };
};


// 컨테이너(컴포넌트/DOM엘리먼트/문자열id) → 실제 DOM id (중첩 wframe 스코프 대응). 내부 유틸(스코프 지역함수)
function __sbResolveId(container) {
    if (!container) { return null; }
    if (typeof container === "string") { return container; }
    if (typeof container.getID === "function") { return container.getID(); }
    if (container.id) { return container.id; }
    return null;
}
